    int n = grid.size();

    vector<int> dr = {1, -1, 0, 0};
    vector<int> dc = {0, 0, 1, -1};

    DisjointSet djs(n * n);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] == 1) {
                int id = i * n + j;
                for (int d = 0; d < 4; d++) {
                    int ni = i + dr[d], nj = j + dc[d];
                    if (isLand(ni, nj, grid)) {
                        int nid = ni * n + nj;
                        if (djs.findUPar(id) != djs.findUPar(nid))
                            djs.unionBySize(id, nid);
                    }
                }
            }
        }
