    int ans = INT_MIN;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] == 0) {
                unordered_set<int> st;
                for (int d = 0; d < 4; d++) {
                    int ni = i + dr[d], nj = j + dc[d];
                    if (isLand(ni, nj, grid)) {
                        int nid = ni * n + nj;
                        st.insert(djs.findUPar(nid));
                    }
                }
                int siz = 0;
                for (auto u : st)
                    siz += djs.size[u];
                ans = max(ans, siz + 1);
            }
        }
    }
    for (int cellNo = 0; cellNo < n * n; cellNo++) {
        ans = max(ans, djs.size[djs.findUPar(cellNo)]);
