        int mid = low + (high - low) / 2;
        int sum = 0;
        for (auto num : nums) {
            sum += (num + mid - 1) / mid;
        }
        if (sum <= threshold) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
}

