Node* copyRandomList(Node* head) {
    if (head == NULL)
        return head;

    // inserting dupli node in between
    Node* orig = head;
    while (orig) {
        Node* temp = orig->next;
        orig->next = new Node(orig->val);
        orig->next->next = temp;
        orig = orig->next->next;
    }
    // setting random pointers
    orig = head;
