    orig = head;
    Node* ans = orig->next;
    while (orig && orig->next) {
        Node* temp = orig->next->next;
        if (orig->next->next)
            orig->next->next = orig->next->next->next;
        orig->next = temp;
        orig = orig->next;
    }
    return ans;
}
