    if (input.empty() && output.empty())
        return -1;

    if (output.empty()) {
        while (!input.empty()) {
            int temp = input.top();
            input.pop();
            output.push(temp);
        }
    }

    int dequeued = output.top();
    output.pop();

    return dequeued;
}

