vector<int> asteroidCollision(vector<int>& asteroids) {
    stack<int> st;
    for (int i = 0; i < asteroids.size(); i++) {
        int siz = abs(asteroids[i]);
        while (!st.empty() && (st.top() > 0 && asteroids[i] < 0) && (st.top() < siz)) {
