    for(int k = i; k <= j; k++){
        int coins = (nums[i - 1] * nums[k] * nums[j + 1]) + fmemo(i, k - 1, nums, dp) + fmemo(k + 1, j, nums, dp);
        ans = max(ans, coins);
    }
    return dp[i][j] = ans;
}

