double myPow(double x, int n) {
    if (n == 0)
        return 1;
    double res = 1;
    bool isNegative = (n < 0);
    n = abs(n);
    while (n > 0) {
        if (n & 1) { // Check if n is odd
            res = res * x;
        }
        x = x * x; // Update x to x^2
        n = n >> 1; // Right-shift n by 1
    }
    return (isNegative) ? 1 / res : res;
}

// Time Complexity: O(log(n))
// Space Complexity: O(1)
